settings.custom_liquid:
{%- assign visuel = blank -%}{%- assign alt = '' -%}
{%- case page.handle -%}
{%- when 'guide-declaration-carport' -%}{%- assign visuel = 'sousabri-guide-declaration.jpg' -%}{%- assign alt = 'Plan de maison et mètre sur une table, préparation de la déclaration préalable' -%}
{%- when 'guide-montage-ancrage' -%}{%- assign visuel = 'sousabri-guide-montage.jpg' -%}{%- assign alt = 'Pièces d un carport en kit posées au sol avant le montage à deux' -%}
{%- when 'devis-carport-cintre-2-pieds' -%}{%- assign visuel = 'devis-carport-cintre-2-pieds-situation.jpg' -%}{%- assign alt = 'Carport aluminium cintré à 2 pieds devant une maison, voiture grise à l abri' -%}
{%- when 'comparatif-carport-tente-garage' -%}{%- assign visuel = 'sousabri-guide-comparatif.jpg' -%}{%- assign alt = 'Carport aluminium à toit cintré et tente-garage blanche côte à côte dans un jardin' -%}
{%- endcase -%}
{%- if visuel != blank -%}
<div class="page-width" style="padding-top:24px"><img src="{{ visuel | file_img_url: '2048x' }}" alt="{{ alt }}" loading="eager" style="width:100%;height:auto;border-radius:6px;display:block"></div>
{%- endif -%}
